#include <stdio.h>

int main() {
    int a[] = {7, 3, 9, 1, 8};
    int first = a[0], second = -1;
    for (int i = 1; i < 5; i++) {
        if (a[i] > first) {
            second = first;
            first = a[i];
        } else if (a[i] > second) {
            second = a[i];
        }
    }
    printf("%d\n", second);
    return 0;
}
